function loadSave(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');if(s){if(Array.isArray(s.progress)&&s.progress.length===3)progress=s.progress.map(n=>THREE.MathUtils.clamp(Math.floor(Number(n)||0),0,3));if(Number.isFinite(s.money))money=Math.max(0,s.money);if(Number.isInteger(s.activeHero)&&s.activeHero>=0&&s.activeHero<3)activeHero=s.activeHero;if(Array.isArray(s.decisions)&&s.decisions.length===3)decisions=s.decisions.map(row=>[0,1,2].map(i=>row?.[i]===0||row?.[i]===1?row[i]:null));if(Array.isArray(s.collectedRelics))collectedRelics=[...new Set(s.collectedRelics.filter(n=>Number.isInteger(n)&&n>=0&&n<12))];if(Array.isArray(s.completedContracts))completedContracts=[...new Set(s.completedContracts.filter(n=>Number.isInteger(n)&&n>=0&&n<contractRoutes.length))];if(Array.isArray(s.discoveredDistricts))s.discoveredDistricts.filter(n=>typeof n==='string'&&zones.some(z=>z.name===n)).forEach(n=>discoveredDistricts.add(n));if(s.garageUpgrades&&typeof s.garageUpgrades==='object')for(const key of ['engine','handling','armor'])garageUpgrades[key]=THREE.MathUtils.clamp(Math.floor(Number(s.garageUpgrades[key])||0),0,3);if(s.graphicsSettings&&typeof s.graphicsSettings==='object')graphicsSettings={...graphicsSettings,...s.graphicsSettings};if(Array.isArray(s.completedServices))completedServices=[...new Set(s.completedServices.filter(n=>n==='ARTS CORNER CAFE'))];if(typeof s.selectedVehicle==='string'&&['SPORT','SEDAN','SUV'].includes(s.selectedVehicle))selectedVehicle=s.selectedVehicle;if(typeof s.audioMuted==='boolean')audioMuted=s.audioMuted;graphicsSettings.quality=['PERFORMANCE','HIGH','ULTRA','EXTREME'].includes(graphicsSettings.quality)?graphicsSettings.quality:'HIGH';graphicsSettings.atmosphere=graphicsSettings.atmosphere==='NEON NIGHT'?'NEON NIGHT':'GOLDEN HOUR';graphicsSettings.volume=THREE.MathUtils.clamp(Number(graphicsSettings.volume)||0,0,100);graphicsSettings.reducedMotion=graphicsSettings.reducedMotion===true;}}catch(e){console.warn('Save data could not be loaded',e)}}
function saveGame(){try{localStorage.setItem(SAVE_KEY,JSON.stringify({version:7,progress,money,activeHero,decisions,collectedRelics,completedContracts,discoveredDistricts:[...discoveredDistricts],garageUpgrades,graphicsSettings,selectedVehicle,completedServices,audioMuted,updatedAt:Date.now()}));setText('save-status','SAVED')}catch(e){setText('save-status','SESSION ONLY')}}

const garagePanel=document.querySelector('#garage-panel');
function upgradeCost(type){return 300+garageUpgrades[type]*350}
function syncGarageUI(){for(const type of ['engine','handling','armor']){const level=garageUpgrades[type],button=document.querySelector('#upgrade-'+type);if(button){button.disabled=level>=3||money<upgradeCost(type);button.textContent=level>=3?'MAX LEVEL':'UPGRADE · $'+upgradeCost(type)+' · LV '+level+' → '+(level+1)}}document.querySelectorAll('[data-vehicle]').forEach(button=>button.classList.toggle('selected',button.dataset.vehicle===selectedVehicle));setText('garage-cash','$'+money);setText('garage-levels','ENGINE '+garageUpgrades.engine+'/3 · HANDLING '+garageUpgrades.handling+'/3 · ARMOR '+garageUpgrades.armor+'/3')}
function toggleGarage(force){if(!garagePanel)return;const open=typeof force==='boolean'?force:garagePanel.hidden;if(open&&(paused||driving))return;garagePanel.hidden=!open;if(open){keys={};document.exitPointerLock?.();syncGarageUI()}}
function buyUpgrade(type){if(!['engine','handling','armor'].includes(type))return;const level=garageUpgrades[type],cost=upgradeCost(type);if(level>=3||money<cost){say(level>=3?'UPGRADE MAXED':'NOT ENOUGH CASH · NEED $'+cost);return}money-=cost;garageUpgrades[type]++;if(type==='armor'){carHealth=Math.min(maxCarHealth(),carHealth+20);setText('car-health',Math.round(carHealth/maxCarHealth()*100)+'%')}syncUI();saveGame();syncGarageUI();say(type.toUpperCase()+' UPGRADED · LEVEL '+garageUpgrades[type])}
['engine','handling','armor'].forEach(type=>document.querySelector('#upgrade-'+type)?.addEventListener('click',()=>buyUpgrade(type)));document.querySelector('#garage-close')?.addEventListener('click',()=>toggleGarage(false));
function initAudio(){if(!audioEnabled||audioContext)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioContext=new AC();engineOsc=audioContext.createOscillator();engineOsc.type='sawtooth';engineGain=audioContext.createGain();engineGain.gain.value=.0001;engineOsc.connect(engineGain);engineGain.connect(audioContext.destination);engineOsc.start();skidOsc=audioContext.createOscillator();skidOsc.type='triangle';skidGain=audioContext.createGain();skidGain.gain.value=.0001;skidOsc.connect(skidGain);skidGain.connect(audioContext.destination);skidOsc.start()}catch(e){console.warn('Audio unavailable',e)}}
function updateAudio(){if(!audioContext||!engineOsc)return;const speed=Math.abs(driveSpeed),volume=audioMuted?0:Number(document.querySelector('#volume')?.value??55)/100;engineOsc.frequency.setTargetAtTime(48+speed*7,audioContext.currentTime,.08);engineGain.gain.setTargetAtTime(driving?volume*(.018+Math.min(speed/27,.6)*.045):.0001,audioContext.currentTime,.12);skidOsc.frequency.setTargetAtTime(180+speed*4,audioContext.currentTime,.08);skidGain.gain.setTargetAtTime(driving&&keys[' ']&&speed>5?volume*.025:.0001,audioContext.currentTime,.06);}
