function syncUI(){const h=storyData[activeHero],m=currentMission();setText('hero-name',h.name);setText('hero-role',h.role);setText('chapter',h.name.split(' ')[0]+' · PERSONAL STORY');setText('cash','$'+money);setText('relic-count',collectedRelics.length+' / 12');syncGarageUI();setText('story-count',String(Math.min(progress[activeHero]+1,3)).padStart(2,'0')+' / 03');setText('mission-title',m?m.title:'STORY COMPLETE');setText('mission-text',m?m.text:'Your chapter is complete. Explore Port Meridian or switch to another protagonist.');setText('cash-reward',m?'+'+'$'+m.reward:'FREE ROAM');document.querySelectorAll('[data-hero]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.hero)===activeHero));moveMarker()}

// Phase 15: campaign journal, generated from the existing saved state.
const journalPanel=document.querySelector('#journal-panel');
function renderJournal(){const host=document.querySelector('#journal-content');if(!host)return;const summary=document.createElement('p');summary.className='journal-summary';summary.textContent='CASH $'+money+' · RELICS '+collectedRelics.length+'/12 · CONTRACTS '+completedContracts.length+'/'+contractRoutes.length+' · DISTRICTS '+discoveredDistricts.size+'/'+zones.length;const cards=storyData.map((hero,index)=>{const card=document.createElement('article');card.className='journal-card';const heading=document.createElement('h3');heading.textContent=hero.name+(index===activeHero?' · ACTIVE':'');const status=document.createElement('p');status.textContent=progress[index]===3?'CHAPTER COMPLETE':progress[index]+'/3 STORY BEATS COMPLETE';const list=document.createElement('ul');hero.missions.forEach((mission,missionIndex)=>{const item=document.createElement('li');const choice=decisions[index][missionIndex];const state=missionIndex<progress[index]?'COMPLETE':missionIndex===progress[index]?'CURRENT':'LOCKED';item.className=missionIndex<progress[index]?'complete':missionIndex===progress[index]?'current':'';item.textContent=mission.title+' · '+state+(choice===0?' · CHOICE A':choice===1?' · CHOICE B':'');list.append(item)});card.append(heading,status,list);return card});host.replaceChildren(summary,...cards)}
function toggleJournal(force){if(!journalPanel)return;const open=typeof force==='boolean'?force:journalPanel.hidden;if(open&&(paused||dialogue||driving)){say('Open the journal while on foot and outside dialogue');return}journalPanel.hidden=!open;document.querySelector('#journal-toggle')?.setAttribute('aria-expanded',String(open));if(open){keys={};document.exitPointerLock?.();renderJournal()}}
document.querySelector('#journal-toggle')?.addEventListener('click',()=>toggleJournal());document.querySelector('#journal-close')?.addEventListener('click',()=>toggleJournal(false));

