function syncSoundButton(){const button=document.querySelector('#sound-toggle');if(button){button.textContent=audioMuted?'SOUND · OFF':'SOUND · ON';button.setAttribute('aria-pressed',String(!audioMuted))}}
document.querySelector('#sound-toggle')?.addEventListener('click',()=>{audioMuted=!audioMuted;if(!audioMuted)initAudio();updateAudio();syncSoundButton();saveGame();say(audioMuted?'GAME AUDIO MUTED':'GAME AUDIO ENABLED')});
function playUiCue(kind='confirm'){if(audioMuted)return;initAudio();if(!audioContext)return;const presets={mission:[660,880],pickup:[880,1174],service:[523,659],confirm:[520]};const notes=presets[kind]||presets.confirm;const volume=Number(document.querySelector('#volume')?.value??55)/100;notes.forEach((frequency,index)=>{const start=audioContext.currentTime+index*.09,osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.035*volume,start+.015);gain.gain.exponentialRampToValueAtTime(.0001,start+.16);osc.connect(gain);gain.connect(audioContext.destination);osc.start(start);osc.stop(start+.18)})}
function switchHero(n){if(n<0||n>2||n===activeHero)return;if(raceState){raceState=null;raceGates.forEach(g=>g.visible=false);setText('race-status','T · START STREET SPRINT')}activeHero=n;stamina=100;buildAvatar(storyData[n].color);const home=[{x:0,z:0},{x:-42,z:-42},{x:42,z:42}][n];if(driving){driving=false;avatar.visible=true;driveSpeed=0;playerCar.position.set(home.x,0,home.z+9)}player.position.set(home.x,0,home.z);player.rotation.y=0;dialogue=null;document.querySelector('#dialogue').hidden=true;syncUI();saveGame();say(storyData[n].name+' — personal story loaded');}
