 if(driving){
  if(raceState){raceState=null;raceGates.forEach(g=>g.visible=false);setText('race-status','T · START STREET SPRINT');say('Street sprint cancelled · vehicle exited')}
  const side=new THREE.Vector3(Math.cos(playerCar.rotation.y),0,-Math.sin(playerCar.rotation.y)).multiplyScalar(3.4);let ex=playerCar.position.x+side.x,ez=playerCar.position.z+side.z;if(collides(ex,ez,1.0)){ex=playerCar.position.x-side.x;ez=playerCar.position.z-side.z}ex=THREE.MathUtils.clamp(ex,-184,184);ez=THREE.MathUtils.clamp(ez,-184,184);if(collides(ex,ez,1.0)){say('No safe space to exit here. Move the car away from the building.');return}driving=false;avatar.visible=true;player.position.set(ex,0,ez);driveSpeed=0;saveGame();
  say('Exited vehicle · press F near the car to drive again');return;
 }
 if(carHealth<=0){say('The sports car is disabled · press R at a checkpoint to repair it');return}if(Math.hypot(player.position.x-playerCar.position.x,player.position.z-playerCar.position.z)>5.5){say('Move closer to the gold sports car to drive it · F');return}
 driving=true;avatar.visible=false;player.position.copy(playerCar.position);initAudio();say('Vehicle entered · WASD drive · SPACE handbrake · F exit'); 
