function startInteraction(){if(paused)return;if(driving){say('Exit the vehicle with F before starting a story interaction');return}if(dialogue){if(dialogue.choosing)return;dialogue.index++;if(dialogue.index>=dialogue.lines.length){dialogue.choosing=true;showDialogue();return}showDialogue();return}const relic=nearestRelic();if(relic){collectRelic(relic);return}const m=currentMission();if(m&&closeToMission()){dialogue={index:0,lines:m.lines,speaker:m.speaker,hero:activeHero,missionIndex:progress[activeHero],choosing:false};showDialogue();return}const nearbyService=nearestCityService();if(nearbyService){useCityService(nearbyService);return}const nearbyPed=nearestPedestrian();if(nearbyPed){talkToPedestrian(nearbyPed);return}if(!m){say('This chapter is complete. Switch protagonists for another story.');return}say('Move closer to the glowing story marker.')}
function setWanted(level,reason='CITY DISTURBANCE'){const next=THREE.MathUtils.clamp(level,0,5);if(next>wantedLevel){const firstAlert=wantedLevel===0;wantedLevel=next;wantedCooldown=24;if(firstAlert){const focus=driving?playerCar.position:player.position;policeCars.forEach((cop,i)=>{const angle=i*Math.PI/2;cop.position.set(THREE.MathUtils.clamp(focus.x+Math.sin(angle)*30,-180,180),0,THREE.MathUtils.clamp(focus.z+Math.cos(angle)*30,-180,180));cop.visible=true})}say('WANTED LEVEL '+wantedLevel+' / 5 · '+reason)}else wantedLevel=next;updateWantedUI()}function updateWantedUI(){const stars=document.querySelector('#wanted-stars');if(stars)stars.textContent='★'.repeat(wantedLevel)+'☆'.repeat(5-wantedLevel);const label=document.querySelector('#wanted-label');if(label)label.textContent=wantedLevel?(wantedLevel>=4?'CITYWIDE RESPONSE · '+wantedLevel+' / 5':wantedLevel>=2?'ACTIVE RESPONSE · '+wantedLevel+' / 5':'PATROL ALERT · '+wantedLevel+' / 5'):'NO ACTIVE PURSUIT'}function beginStreetSprint(){if(!driving){say('Enter your gold sports car first · press F');return}if(raceState){say('Route already active · follow the glowing gates');return}raceState={next:0,elapsed:0,type:'sprint',route:raceRoute,reward:0};raceGates.forEach((g,i)=>{g.visible=i===0});say('STREET SPRINT STARTED · FOLLOW THE GOLD GATES')}function beginCityContract(){if(paused||driving||raceState)return;const index=contractRoutes.findIndex((c,i)=>!completedContracts.includes(i));if(index<0){say('ALL CITY CONTRACTS COMPLETE · THANK YOU, PORT MERIDIAN');return}const job=contractRoutes[index];raceState={next:0,elapsed:0,type:'contract',route:job.route,reward:job.reward,contractIndex:index,incidents:0};raceGates.forEach((g,i)=>{g.position.set(job.route[i]?.x??0,.25,job.route[i]?.z??0);g.visible=i===0});setText('race-status','CITY CONTRACT · '+job.name);say('CONTRACT ACCEPTED · '+job.name+' · FOLLOW THE ROUTE')}function updateRace(dt){
 if(!raceState)return;
 raceState.elapsed+=dt;
 const route=raceState.route||raceRoute;
 const target=route[raceState.next];
 const focus=raceState.type==='contract'?player.position:playerCar.position;
 if(target&&Math.hypot(focus.x-target.x,focus.z-target.z)<7){
  raceGates[raceState.next].visible=false;
  raceState.next++;
  if(raceState.next>=route.length){
   const seconds=raceState.elapsed,isContract=raceState.type==='contract',incidentsAtFinish=raceState.incidents||0;
   const cleanBonus=isContract&&incidentsAtFinish===0?Math.round(raceState.reward*.2):0;
   const reward=isContract?raceState.reward+cleanBonus:Math.max(450,Math.round(1100-seconds*4));
   money+=reward;
   if(isContract)completedContracts.push(raceState.contractIndex);else nitroFuel=100;
   raceState=null;
   raceGates.forEach(g=>g.visible=false);
   setText('cash','$'+money);
   setText('race-status','T · START STREET SPRINT');
   saveGame();
   const resultText=isContract?'CITY CONTRACT COMPLETE · '+seconds.toFixed(1)+'s · +$'+reward+(cleanBonus?' · CLEAN DELIVERY BONUS +$'+cleanBonus:' · INCIDENTS '+incidentsAtFinish):'STREET SPRINT COMPLETE · '+seconds.toFixed(1)+'s · +$'+reward+' · NITRO REFILLED';
   say(resultText);
  }else{
   raceGates.forEach((g,i)=>{g.visible=i===raceState.next});
   say('CHECKPOINT '+raceState.next+' / '+route.length);
  }
 }
 setText('race-status',raceState?(raceState.type==='contract'?'CONTRACT ':'SPRINT ')+(raceState.next+1)+'/'+(raceState.route||raceRoute).length+' · '+raceState.elapsed.toFixed(1)+'s':'T · START STREET SPRINT');
}
function finishMission(choice){if(!dialogue)return;const hero=dialogue.hero,missionIndex=dialogue.missionIndex,m=storyData[hero].missions[missionIndex];if(!m)return;const bonus=(hero===0&&choice===1)||(hero===1&&choice===1)||(hero===2&&choice===0);const reward=Math.round(m.reward*(bonus?1.25:1));decisions[hero][missionIndex]=choice;progress[hero]=Math.max(progress[hero],missionIndex+1);money+=reward;playUiCue('mission');dialogue=null;document.querySelector('#dialogue').hidden=true;document.querySelector('#choice-options').hidden=true;document.querySelector('#continue-dialogue').hidden=false;syncUI();saveGame();say((progress[hero]>=3?'CHAPTER COMPLETE':'CHOICE RECORDED')+' · +$'+reward)}
